mapper.select:
SELECT T2.TYPE_6 assetType, T1.FINPROD_MARKET_ID assetId, T1.FINPROD_ABBR assetName, T1.ISSUE_AMT amount, T1.FINPROD_ID, DATE_FORMAT(T3.TRADE_DATE, '%Y-%m-%d') tradeDate, DATE_FORMAT(T1.VDATE, '%Y-%m-%d') vDate, DATE_FORMAT(T1.MDATE, '%Y-%m-%d') mDate, t1.CCY, T4.PAY_CYCLE FROM FIN_PRODUCT T1 LEFT JOIN FIN_PRODUCT_TYPE T2 ON T1.FINPROD_ID = T2.FINPROD_ID LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL T3 ON T1.FINPROD_ID = T3.FINPROD_ID LEFT JOIN FIN_CASH_PAY_RULE T4 ON T1.FINPROD_ID = T4.FINPROD_ID
NOT EXISTS (SELECT 1 FROM TRD_FIN_PRODUCT_DEAL_TOTAL TFT WHERE TFT.FINPROD_ID = T3.FINPROD_ID AND TFT.TRADE_DATE < T3.TRADE_DATE)
AND T1.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F18}
#{item}
and T1.FINPROD_MARKET_ID = #{assetId}
order by T1.MDATE desc
